const { spawnSync } = require('child_process');
const fs = require('fs');

const ADB = 'C:\\\\Users\\\\hzq00\\\\Downloads\\\\platform-tools-latest-windows\\\\platform-tools\\\\adb.exe';
const SERIAL = 'AVNS023705001888';

function run(args, timeoutMs = 60000) {
  const r = spawnSync(ADB, ['-s', SERIAL, 'shell', ...args], {
    encoding: 'utf8', timeout: timeoutMs, windowsHide: true,
  });
  return {
    cmd: 'adb -s ' + SERIAL + ' shell ' + args.join(' '),
    status: r.status,
    error: r.error ? String(r.error) : null,
    stdout: (r.stdout || '').replace(/\\r\\n/g, '\\n'),
    stderr: (r.stderr || '').replace(/\\r\\n/g, '\\n'),
  };
}

const results = [];
results.push(run(['which', 'perfetto']));
results.push(run(['perfetto', '--help']));
results.push(run(['id']));
results.push(run(['ps', '-A']).then ? null : (() => { const r = run(['ps', '-A']); results[results.length-1] = {...r, filtered: (r.stdout||'').split('\\n').filter(l => /traced|perfetto/i.test(l))}; return null; })());
results.push(run(['ls', '-ld', '/data/misc/perfetto-traces']));
results.push(run(['stat', '/data/misc/perfetto-traces']));
results.push(run(['ls', '-l', '/data/misc/perfetto-traces']));
results.push(run(['ls', '-ld', '/data/local/tmp']));
results.push(run(['ls', '-ld', '/dev/socket/traced_consumer', '/dev/socket/traced_producer']));
results.push(run(['getprop', 'ro.build.version.sdk']));
results.push(run(['getprop', 'ro.build.version.release']));
results.push(run(['getprop', 'ro.product.model']));
results.push(run(['getprop', 'ro.product.name']));

const clean = results.filter(Boolean);
for (const r of clean) {
  console.log('='.repeat(24));
  console.log('CMD:', r.cmd);
  console.log('STATUS:', r.status, r.error ? (' ERROR: ' + r.error) : '');
  console.log('STDOUT:', r.stdout);
  if (r.filtered) console.log('FILTERED traced/perfetto:', r.filtered.join('\\n'));
  console.log('STDERR:', r.stderr);
}
fs.writeFileSync('raw_probe.json', JSON.stringify(clean, null, 2), 'utf8');
console.log('saved raw_probe.json');
